reference_solution:
def mergeTwoLists(l1, l2):
    dummy = cur = ListNode(0)
    while l1 and l2:
        if l1.val <= l2.val:
            cur.next = l1
            l1 = l1.next
        else:
            cur.next = l2
            l2 = l2.next
        cur = cur.next
    cur.next = l1 or l2
    return dummy.next

brute_force_solution:
def mergeTwoLists(l1, l2):
    vals = []
    for l in (l1, l2):
        while l:
            vals.append(l.val)
            l = l.next
    vals.sort()
    out = None
    for v in reversed(vals):
        out = ListNode(v, out)
    return out

